// Operadores bitwise trabajan sobre los bits individuales del número
// & (AND bitwise): ambos bits deben ser 1
// | (OR bitwise): al menos un bit debe ser 1
// ^ (XOR bitwise): exactamente uno de los dos bits debe ser 1
// ~ (NOT bitwise): invierte todos los bits
// << (left shift): desplaza bits a la izquierda (multiplica por 2)
// >> (right shift): desplaza bits a la derecha (divide por 2)

// Ejemplo: flags de estado de personaje con bits
[System.Flags]
enum CharacterState
{
    None      = 0,        // 0000
    IsRunning = 1 << 0,   // 0001
    IsJumping = 1 << 1,   // 0010
    IsAttacking = 1 << 2, // 0100
    IsStunned = 1 << 3    // 1000
}

CharacterState state = CharacterState.IsRunning | CharacterState.IsJumping; // 0011

// Verificar si está corriendo:
bool running = (state & CharacterState.IsRunning) != 0; // true

// Activar un flag:
state |= CharacterState.IsAttacking; // 0111

// Desactivar un flag:
state &= ~CharacterState.IsJumping;  // 0101

// Toggle (invertir) un flag:
state ^= CharacterState.IsStunned;   // alterna entre activo e inactivo

